OWW={}; OWW.f=CreateFrame("Frame","OWWATCH",UIParent); OWW.a=nil; OWW.b=nil; OWW.f:SetScript("OnUpdate",function() local a=GameTooltip:IsShown() and 1 or 0; local b=GameTooltip:IsVisible() and 1 or 0; if a~=OWW.a or b~=OWW.b then OWW.a=a; OWW.b=b; DEFAULT_CHAT_FRAME:AddMessage(string.format("t=%.2f shown=%d visible=%d",GetTime(),a,b)) end end); DEFAULT_CHAT_FRAME:AddMessage("W3-OK")